theorem t3 (hfa : FnUb f a) (hgb : FnUb g b) (nng : FnLb g 0) (nna : 0 ≤ a) :
    FnUb (fun x ↦ f x * g x) (a * b) :=
  if g x < 0 then (hfa x).trans ((hgb x).trans nng) else (hfa x).trans (hgb x.le_of_nonneg nna)

theorem t4 {c : ℝ} (mf : Monotone f) (nnc : 0 ≤ c) : Monotone fun x ↦ c * f x :=
  mul_le_mul_of_nonneg_left _ nnc <|
    MF.mphantom (since := (Old.MF.mul_le_mul_left mf _).of_nonneg (by positivity)) {aleb := mf aleb}
